CREATE TABLE IF NOT EXISTS roles(id BIGSERIAL PRIMARY KEY,role_name VARCHAR(60) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS permissions(id BIGSERIAL PRIMARY KEY,permission_name VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role_id BIGINT REFERENCES roles(id) ON DELETE CASCADE,permission_id BIGINT REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(254) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role_id BIGINT REFERENCES roles(id),status VARCHAR(20) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS employee(id BIGSERIAL PRIMARY KEY,employee_code VARCHAR(50) UNIQUE,name VARCHAR(150) NOT NULL,email VARCHAR(254) UNIQUE,phone VARCHAR(20),salary NUMERIC(12,2),designation VARCHAR(100));
CREATE TABLE IF NOT EXISTS academic_year(id BIGSERIAL PRIMARY KEY,year_name VARCHAR(20) UNIQUE NOT NULL,start_date DATE,end_date DATE,status VARCHAR(20) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS academic_class(id BIGSERIAL PRIMARY KEY,class_name VARCHAR(50) NOT NULL,academic_year_id BIGINT REFERENCES academic_year(id),total_seats INT DEFAULT 0,available_seats INT DEFAULT 0,admission_open BOOLEAN DEFAULT FALSE,UNIQUE(class_name,academic_year_id));
CREATE TABLE IF NOT EXISTS admission_application(id BIGSERIAL PRIMARY KEY,student_name VARCHAR(150) NOT NULL,date_of_birth DATE,parent_name VARCHAR(150) NOT NULL,parent_phone VARCHAR(20) NOT NULL,email VARCHAR(254),class_id BIGINT REFERENCES academic_class(id),academic_year_id BIGINT REFERENCES academic_year(id),application_status VARCHAR(30) DEFAULT 'PENDING',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,application_id BIGINT REFERENCES admission_application(id),amount NUMERIC(12,2) NOT NULL,provider VARCHAR(40),provider_order_id VARCHAR(150),provider_payment_id VARCHAR(150),payment_status VARCHAR(30) DEFAULT 'PENDING',paid_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS student(id BIGSERIAL PRIMARY KEY,admission_number VARCHAR(60) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,parent_name VARCHAR(150),parent_phone VARCHAR(20),class_id BIGINT REFERENCES academic_class(id),academic_year_id BIGINT REFERENCES academic_year(id),application_id BIGINT UNIQUE REFERENCES admission_application(id),created_at TIMESTAMPTZ DEFAULT NOW());
INSERT INTO roles(role_name) VALUES('SUPER_ADMIN'),('PRINCIPAL'),('TEACHER'),('ADMINISTRATION'),('ACCOUNTANT'),('STUDENT') ON CONFLICT DO NOTHING;
INSERT INTO permissions(permission_name) VALUES('STUDENT_CREATE'),('STUDENT_READ'),('STUDENT_UPDATE'),('STUDENT_DELETE'),('EMPLOYEE_MANAGE'),('ADMISSION_REVIEW'),('FEE_MANAGE'),('ROLE_MANAGE') ON CONFLICT DO NOTHING;
